//! What Python itself does, where PyMini did otherwise or had nothing: each
//! case's expected text is CPython's answer to the same script. Generated by
//! `tests/cpython_parity_gen.py`; edit the cases there, not here. Sorting, dict keys,
//! frozenset and bytearray, keyword arguments of builtins, slice and starred
//! assignment, `raise … from`, `re.compile` and lookaround, json options,
//! int literals, `#` formats, the math, str and itertools additions, whitespace
//! splits, exact integer comparisons, `range` loops past the container cap, and
//! the wording of call and division errors.

mod common;
use common::big_stack;

use wm_python::interp::{Limits, Runtime, STANDARD_MODULES};

/// The last line's value, with the Python standard library on, under the
/// default limits a plugin runs with.
fn py(src: &'static str) -> String {
    big_stack(move || {
        let mut rt = Runtime::new(Limits::default(), STANDARD_MODULES);
        rt.enable_python_stdlib();
        match rt.run(src) {
            Ok(v) => v.to_str(),
            Err(e) => panic!("{src}\n{e}"),
        }
    })
}

#[test]
fn sort_is_n_log_n_and_stable() {
    assert_eq!(
        py(r#"import random
random.seed(5)
xs = [random.random() for _ in range(8000)]
ys = sorted(xs)
pairs = sorted([(1, 'b'), (0, 'a'), (1, 'a')], key=lambda t: t[0], reverse=True)
zs = [3, 1, 2]
zs.sort(reverse=True)
repr((all(ys[i] <= ys[i + 1] for i in range(len(ys) - 1)), pairs, zs, sorted(['b', 'A', 'c'], key=str.lower)))"#),
        r#"(True, [(1, 'b'), (1, 'a'), (0, 'a')], [3, 2, 1], ['A', 'b', 'c'])"#
    );
}

#[test]
fn sort_refuses_mixed_types() {
    assert_eq!(
        py(r#"try:
    sorted([1, 'a'])
    r = 'sorted'
except TypeError:
    r = 'TypeError'
r"#),
        r#"TypeError"#
    );
}

#[test]
fn equal_numbers_are_one_key() {
    assert_eq!(
        py(r#"d = {1: 'a'}
d[True] = 'b'
d[1.0] = 'c'
repr((d, len({1, True, 1.0}), {1: 'x'} == {1.0: 'x'}, 2.0 in {2}))"#),
        r#"({1: 'c'}, 1, True, True)"#
    );
}

#[test]
fn hash_and_eq_decide_keys() {
    assert_eq!(
        py(r#"class V:
    def __init__(self, v):
        self.v = v
    def __eq__(self, o):
        return isinstance(o, V) and self.v == o.v
    def __hash__(self):
        return hash(self.v)
s = {V(1), V(1), V(2)}
d = {V(1): 'x'}
d[V(1)] = 'y'
repr((len(s), d[V(1)], len(d), V(1) in s, V(3) in s, (V(1), 2) in {(V(1), 2)}))"#),
        r#"(2, 'y', 1, True, False, True)"#
    );
}

#[test]
fn constant_hash_still_separates_unequal() {
    assert_eq!(
        py(r#"class C:
    def __init__(self, v):
        self.v = v
    def __eq__(self, o):
        return self.v == o.v
    def __hash__(self):
        return 0
s = {C(1), C(2), C(1)}
repr(len(s))"#),
        r#"2"#
    );
}

#[test]
fn hash_none_is_unhashable() {
    assert_eq!(
        py(r#"class U:
    __hash__ = None
try:
    {U()}
    r = 'hashed'
except TypeError:
    r = 'TypeError'
r"#),
        r#"TypeError"#
    );
}

