#[test]
fn keyword_arguments_of_builtins() {
    assert_eq!(
        py(r#"from collections import OrderedDict
d = dict(a=1)
d.update({'b': 2}, c=3)
repr((d, dict([('x', 1)], y=2), dict(OrderedDict(z=1)), list(enumerate('ab', start=1)), sum([[1], [2]], start=[]), int('ff', base=16), str(b'hi', 'utf-8'), dict.fromkeys('ab', 0), list(map(str.strip, [' a ', 'b ']))))"#),
        r#"({'a': 1, 'b': 2, 'c': 3}, {'x': 1, 'y': 2}, {'z': 1}, [(1, 'a'), (2, 'b')], [1, 2], 255, 'hi', {'a': 0, 'b': 0}, ['a', 'b'])"#
    );
}

