#[test]
fn raise_from_keeps_the_cause() {
    assert_eq!(
        py(r#"class E(Exception):
    pass
try:
    try:
        raise KeyError('k')
    except KeyError as inner:
        raise ValueError('wrapped') from inner
except ValueError as e:
    first = (str(e), repr(e.__cause__))
try:
    raise E('x') from first and None
except E as e:
    second = e.__cause__
repr((first, second))"#),
        r#"(('wrapped', "KeyError('k')"), None)"#
    );
}

#[test]
fn exception_args_and_messages() {
    assert_eq!(
        py(r#"try:
    {}['k']
except KeyError as e:
    k = (str(e), repr(e), e.args)
v = ValueError('a', 1)
msgs = []
for f in (lambda: [][1], lambda: 'ab'[5], lambda: (1,)[3], lambda: '1' + 1, lambda: int('x')):
    try:
        f()
    except Exception as e:
        msgs.append(str(e))
repr((k, str(v), v.args, repr(ValueError()), str(KeyError('m')), msgs))"#),
        r#"(("'k'", "KeyError('k')", ('k',)), "('a', 1)", ('a', 1), 'ValueError()', "'m'", ['list index out of range', 'string index out of range', 'tuple index out of range', 'can only concatenate str (not "int") to str', "invalid literal for int() with base 10: 'x'"])"#
    );
}

#[test]
fn function_attributes_and_wraps() {
    assert_eq!(
        py(r#"import functools
def deco(fn):
    @functools.wraps(fn)
    def wrapper(*a):
        return fn(*a)
    return wrapper
@deco
def named():
    pass
def f():
    pass
f.calls = 3
repr((named.__name__, named.__wrapped__.__name__, f.calls))"#),
        r#"('named', 'named', 3)"#
    );
}

#[test]
fn re_compile_and_patterns() {
    assert_eq!(
        py(r#"import re
p = re.compile(r'(\d+)-(\d+)', re.I)
q = re.compile(r'\w+')
repr((p.findall('1-2 33-4'), p.sub(r'\2-\1', '1-2'), p.pattern, p.groups, bool(p.search('x9-9')), q.match('ab cd').group(), q.findall('ab cd', 2), re.search(q, 'zz').group()))"#),
        r#"([('1', '2'), ('33', '4')], '2-1', '(\\d+)-(\\d+)', 2, True, 'ab', ['cd'], 'zz')"#
    );
}

#[test]
fn regex_lookaround() {
    assert_eq!(
        py(r#"import re
repr((re.findall(r'(?<=\$)\d+(?=\.)', '$12. $3.'), re.sub(r'(?<!\d)0', 'o', '10 0'), bool(re.search(r'foo(?!bar)', 'foobar')), re.findall(r'\b\w+(?=ing\b)', 'going doing'), re.findall(r'(?<=ab|cd)x', 'abx cdx efx')))"#),
        r#"(['12', '3'], '10 o', False, ['go', 'do'], ['x', 'x'])"#
    );
}

#[test]
fn regex_backreferences_and_inline_flags() {
    assert_eq!(
        py(r#"import re
repr((re.findall(r'(\w)\1', 'aabbcd'), re.sub(r'(?P<w>\w+) (?P=w)', r'\g<w>', 'the the end'), bool(re.fullmatch(r'(a|b)\1', 'ab')), re.findall(r'(?i)abc', 'ABC abc'), re.sub(r'(?m)^', '> ', 'a\nb')))"#),
        r#"(['a', 'b'], 'the end', False, ['ABC', 'abc'], '> a\n> b')"#
    );
}

